CREATE TABLE chat_conversations(id TEXT PRIMARY KEY,title TEXT NOT NULL,row_version INTEGER NOT NULL CHECK(row_version>0),created_at TEXT NOT NULL,updated_at TEXT NOT NULL) STRICT;
CREATE TABLE chat_runs(id TEXT PRIMARY KEY,conversation_id TEXT NOT NULL REFERENCES chat_conversations(id),user_message_id TEXT NOT NULL,assistant_message_id TEXT NOT NULL,status TEXT NOT NULL,request_json TEXT NOT NULL CHECK(json_valid(request_json)),model_json TEXT CHECK(model_json IS NULL OR json_valid(model_json)),last_event_seq INTEGER NOT NULL DEFAULT 0,lease_token TEXT,lease_expires_at TEXT,error_code TEXT,usage_json TEXT NOT NULL DEFAULT '{"input_tokens":null,"output_tokens":null}' CHECK(json_valid(usage_json)),finish_reason TEXT,created_at TEXT NOT NULL,updated_at TEXT NOT NULL) STRICT;
CREATE UNIQUE INDEX chat_single_active_run ON chat_runs(conversation_id) WHERE status IN ('queued','running');
CREATE INDEX chat_pending_runs ON chat_runs(status,created_at,id);
CREATE TABLE chat_messages(id TEXT PRIMARY KEY,conversation_id TEXT NOT NULL REFERENCES chat_conversations(id),ordinal INTEGER NOT NULL CHECK(ordinal>0),role TEXT NOT NULL CHECK(role IN ('user','assistant')),content TEXT NOT NULL,created_at TEXT NOT NULL,run_id TEXT NOT NULL REFERENCES chat_runs(id),UNIQUE(conversation_id,ordinal),UNIQUE(run_id,role)) STRICT;
CREATE TABLE chat_run_events(run_id TEXT NOT NULL REFERENCES chat_runs(id),seq INTEGER NOT NULL CHECK(seq>0),kind TEXT NOT NULL CHECK(kind IN ('text_delta','status')),text_delta TEXT,status TEXT NOT NULL,PRIMARY KEY(run_id,seq)) STRICT;
